{'content': '// Battery Case for 4x Olympus BLS-5 Batteries
// Battery dimensions: 56mm x 36mm x 13mm
// Arrangement: 4x1 linear, batteries upright on smallest face (13x36mm base)
// Batteries face each other with largest face (56x36mm)

$fn = 40;

// Battery dimensions
bat_length = 56;  // height when upright
bat_width = 36;   // depth
bat_thick = 13;   // thickness (side by side)

// Case parameters
wall = 2.5;           // wall thickness
floor_thick = 3;      // floor thickness
clearance = 0.6;      // clearance around battery
snap_protrude = 1.2;  // how far snap protrudes into slot
snap_height = 5;      // height of snap ridge
snap_from_top = 10;   // distance from top to snap
finger_hole_dia = 18; // diameter of finger hole

// Calculated dimensions
slot_width = bat_thick + clearance * 2;  // width per slot
slot_depth = bat_width + clearance * 2;  // depth
slot_height = bat_length + clearance;    // height

num_batteries = 4;
divider_thick = 2;  // thickness between slots

// Total case dimensions
case_width = num_batteries * slot_width + (num_batteries - 1) * divider_thick + 2 * wall;
case_depth = slot_depth + 2 * wall;
case_height = slot_height + floor_thick;

echo("Case dimensions:", case_width, "x", case_depth, "x", case_height);

// Snap-fit ridge module - angled for easy insertion
module snap_ridge(length) {
    // Ramp on top for insertion, vertical face on bottom for retention
    snap_base = snap_protrude * 0.4;

    translate([0, 0, 0])
    linear_extrude(height = length)
    polygon([
        [0, 0],
        [snap_protrude, snap_height * 0.6],
        [snap_protrude, snap_height * 0.7],
        [snap_base, snap_height],
        [0, snap_height]
    ]);
}

// Single battery slot cavity
module battery_slot() {
    cube([slot_width, slot_depth, slot_height + 1]);
}

// Finger hole that goes through the floor
module finger_hole() {
    // Oval-shaped finger hole
    hull() {
        translate([slot_width/2, slot_depth/2 - 5, -1])
            cylinder(h = floor_thick + 2, d = finger_hole_dia);
        translate([slot_width/2, slot_depth/2 + 5, -1])
            cylinder(h = floor_thick + 2, d = finger_hole_dia);
    }
}

// Snap ridges for one slot (on front and back walls)
module slot_snaps(slot_x) {
    snap_z = floor_thick + slot_height - snap_from_top - snap_height;
    snap_length = slot_width - 2;  // slightly narrower than slot

    // Front wall snap (protrudes backward into slot)
    translate([slot_x + 1, wall - 0.01, snap_z])
        rotate([90, 0, 90])
            snap_ridge(snap_length);

    // Back wall snap (protrudes forward into slot)
    translate([slot_x + slot_width - 1, wall + slot_depth + 0.01, snap_z])
        rotate([90, 0, -90])
            snap_ridge(snap_length);
}

// Main case body
module case_body() {
    difference() {
        // Outer shell
        cube([case_width, case_depth, case_height]);

        // Carve out battery slots
        for (i = [0:num_batteries - 1]) {
            slot_x = wall + i * (slot_width + divider_thick);

            // Main slot
            translate([slot_x, wall, floor_thick])
                battery_slot();

            // Finger hole through floor
            translate([slot_x, wall, 0])
                finger_hole();
        }

        // Chamfer top outer edges for print quality
        chamfer = 1.5;
        translate([-0.1, -0.1, case_height - chamfer])
            difference() {
                cube([case_width + 0.2, chamfer + 0.1, chamfer + 0.1]);
                translate([0, chamfer, 0])
                    rotate([45, 0, 0])
                        cube([case_width + 0.2, chamfer * 2, chamfer * 2]);
            }
        translate([-0.1, case_depth - chamfer, case_height - chamfer])
            difference() {
                cube([case_width + 0.2, chamfer + 0.1, chamfer + 0.1]);
                translate([0, 0, 0])
                    rotate([45, 0, 0])
                        cube([case_width + 0.2, chamfer * 2, chamfer * 2]);
            }
    }
}

// Add grip texture to sides
module grip_texture() {
    groove_spacing = 4;
    groove_depth = 0.8;
    groove_width = 1.5;

    for (z = [10 : groove_spacing : case_height - 10]) {
        // Left side
        translate([-0.1, wall + 5, z])
            rotate([0, 90, 0])
                cylinder(h = groove_depth + 0.1, d = groove_width, $fn = 20);
        translate([-0.1, case_depth - wall - 5, z])
            rotate([0, 90, 0])
                cylinder(h = groove_depth + 0.1, d = groove_width, $fn = 20);

        // Right side
        translate([case_width - groove_depth, wall + 5, z])
            rotate([0, 90, 0])
                cylinder(h = groove_depth + 0.1, d = groove_width, $fn = 20);
        translate([case_width - groove_depth, case_depth - wall - 5, z])
            rotate([0, 90, 0])
                cylinder(h = groove_depth + 0.1, d = groove_width, $fn = 20);
    }
}

// Complete battery case
module battery_case() {
    difference() {
        union() {
            case_body();

            // Add snap ridges to each slot
            for (i = [0:num_batteries - 1]) {
                slot_x = wall + i * (slot_width + divider_thick);
                slot_snaps(slot_x);
            }
        }

        // Grip texture
        grip_texture();
    }
}

// Render the case
battery_case();
'}

