slot_depth = bat_width + clearance * 2;  // depth ~37.2mm
slot_height = bat_length + clearance + 2; // height ~58.6mm (extra for easy removal)

num_batteries = 4;
divider_thick = 2.5;  // thickness between slots

// Total case dimensions
case_width = num_batteries * slot_width + (num_batteries - 1) * divider_thick + 2 * wall;
case_depth = slot_depth + 2 * wall;
case_height = slot_height + floor_thick;

echo("Case dimensions:", case_width, "x", case_depth, "x", case_height);

// Snap-fit ridge module - flexible lip for retention
module snap_ridge(length) {
    // Creates a snap lip that flexes during insertion
    // Angled top ramp, vertical retention face at bottom

    linear_extrude(height = length)
    polygon([
        [0, 0],
        [0, snap_height],
        [snap_protrude * 0.3, snap_height],
        [snap_protrude, snap_height * 0.65],
        [snap_protrude, snap_height * 0.55],
        [snap_protrude * 0.5, snap_height * 0.35],
        [snap_protrude * 0.5, 0]
    ]);
}

// Single battery slot cavity
module battery_slot() {
    // Main cavity
    cube([slot_width, slot_depth, slot_height + 1]);

    // Slight chamfer at top edges for easier insertion
    chamfer = 1;
    translate([0, 0, slot_height - chamfer])
        linear_extrude(height = chamfer + 1, scale = [1 + 2*chamfer/slot_width, 1 + 2*chamfer/slot_depth])
            translate([-chamfer, -chamfer, 0])
                square([slot_width + 2*chamfer, slot_depth + 2*chamfer]);
