// Main case body
module case_body() {
    difference() {
        // Outer shell with slight fillet on bottom edges
        hull() {
            translate([1, 1, 0])
                cylinder(r = 1, h = 0.1);
            translate([case_width - 1, 1, 0])
                cylinder(r = 1, h = 0.1);
            translate([1, case_depth - 1, 0])
                cylinder(r = 1, h = 0.1);
            translate([case_width - 1, case_depth - 1, 0])
                cylinder(r = 1, h = 0.1);
            translate([0, 0, 1])
                cube([case_width, case_depth, case_height - 1]);
        }

        // Carve out battery slots
        for (i = [0:num_batteries - 1]) {
            slot_x = wall + i * (slot_width + divider_thick);

            // Main slot
            translate([slot_x, wall, floor_thick])
                battery_slot();

            // Finger hole through floor
            translate([slot_x, wall, 0])
                finger_hole();

            // Relief cuts for snap flexibility
            snap_relief(slot_x, true);
            snap_relief(slot_x, false);
        }
    }
}

// Add label indents on dividers
module labels() {
    label_depth = 0.6;
    label_size = 6;

    for (i = [0:num_batteries - 1]) {
        slot_center_x = wall + i * (slot_width + divider_thick) + slot_width/2;
        // Number on front
        translate([slot_center_x, -0.1, case_height - 15])
            rotate([90, 0, 0])
                linear_extrude(height = label_depth + 0.1)
                    text(str(i + 1), size = label_size, halign = "center", valign = "center");
    }
}

// Complete battery case
module battery_case() {
    difference() {
        union() {
            case_body();

            // Add snap ridges to each slot
            for (i = [0:num_batteries - 1]) {
                slot_x = wall + i * (slot_width + divider_thick);
                slot_snaps(slot_x);
            }
        }

        // Add labels
        labels();
    }
}

// Render the case
battery_case();
