{'content': '// Battery Case for 4x Olympus BLS-5 Batteries
// Battery dimensions: 56mm x 36mm x 13mm
// Arrangement: 4x1 linear, batteries upright on smallest face (13x36mm base)
// Batteries face each other with largest face (56x36mm)
// Designed to print upright without supports

$fn = 50;

// Battery dimensions
bat_length = 56;  // height when upright
bat_width = 36;   // depth
bat_thick = 13;   // thickness (side by side)

// Case parameters
wall = 2.5;           // wall thickness
floor_thick = 3;      // floor thickness
clearance = 0.6;      // clearance around battery
snap_protrude = 1.4;  // how far snap protrudes into slot
snap_height = 5;      // height of snap ridge
snap_from_top = 8;    // distance from top to snap center
finger_hole_dia = 16; // diameter of finger hole

// Calculated dimensions
slot_width = bat_thick + clearance * 2;  // width per slot ~14.2mm
slot_depth = bat_width + clearance * 2;  // depth ~37.2mm
slot_height = bat_length + 3;            // height ~59mm (extra for grip)

num_batteries = 4;
divider_thick = 2.5;  // thickness between slots

// Total case dimensions
case_width = num_batteries * slot_width + (num_batteries - 1) * divider_thick + 2 * wall;
case_depth = slot_depth + 2 * wall;
case_height = slot_height + floor_thick;

echo("Case dimensions (WxDxH):", case_width, "x", case_depth, "x", case_height);

// Snap-fit ridge module - flexible lip for retention
module snap_ridge(length) {
    // Creates a snap lip that flexes during insertion
    // 45-degree ramp on top for easy insertion
    // Slight undercut at bottom for retention

    linear_extrude(height = length)
    polygon([
        [0, 0],
        [0, snap_height],
        [snap_protrude * 0.25, snap_height],          // small flat top
        [snap_protrude, snap_height * 0.5],           // 45° ramp
        [snap_protrude, snap_height * 0.4],           // retention point
        [snap_protrude * 0.4, snap_height * 0.2],     // undercut angle
        [snap_protrude * 0.4, 0]
    ]);
}

// Single battery slot cavity
module battery_slot() {
    // Main cavity
    cube([slot_width, slot_depth, slot_height + 1]);

    // Entry chamfer at top for easier battery insertion
    chamfer = 1.5;
    translate([-chamfer, -chamfer, slot_height])
        linear_extrude(height = chamfer + 1, scale = 0.01)
            offset(r = 0.5)
                square([slot_width + 2*chamfer, slot_depth + 2*chamfer]);
}

// Finger hole that goes through the floor
module finger_hole() {
    // Oval-shaped finger hole centered in slot
    hull() {
        translate([slot_width/2, slot_depth/2 - 5, -1])
            cylinder(h = floor_thick + 2, d = finger_hole_dia);
        translate([slot_width/2, slot_depth/2 + 5, -1])
            cylinder(h = floor_thick + 2, d = finger_hole_dia);
    }
}

// Relief slot behind snap to allow flexing (print-friendly version)
module snap_relief(slot_x, front) {
    relief_depth = 1.0;
    relief_height = snap_height + 6;
    relief_width = slot_width - 4;
    snap_z = floor_thick + slot_height - snap_from_top - snap_height - 1;

    if (front) {
        translate([slot_x + 2, 0.5, snap_z])
            cube([relief_width, relief_depth, relief_height]);
    } else {
        translate([slot_x + 2, case_depth - 0.5 - relief_depth, snap_z])
            cube([relief_width, relief_depth, relief_height]);
    }
}

// Snap ridges for one slot (on front and back walls)
module slot_snaps(slot_x) {
    snap_z = floor_thick + slot_height - snap_from_top - snap_height;
    snap_length = slot_width - 4;  // slightly narrower than slot

    // Front wall snap (protrudes backward into slot)
    translate([slot_x + 2, wall, snap_z])
        rotate([90, 0, 90])
            snap_ridge(snap_length);

    // Back wall snap (protrudes forward into slot)  
    translate([slot_x + slot_width - 2, case_depth - wall, snap_z])
        rotate([90, 0, -90])
            snap_ridge(snap_length);
}

// Main case body
module case_body() {
    difference() {
        // Outer shell with rounded bottom edges for bed adhesion
        minkowski() {
            translate([1.5, 1.5, 0])
                cube([case_width - 3, case_depth - 3, case_height - 0.5]);
            cylinder(r = 1.5, h = 0.5);
        }

        // Carve out battery slots
        for (i = [0:num_batteries - 1]) {
            slot_x = wall + i * (slot_width + divider_thick);

            // Main slot
            translate([slot_x, wall, floor_thick])
                battery_slot();

            // Finger hole through floor
            translate([slot_x, wall, 0])
                finger_hole();

            // Relief cuts for snap flexibility
            snap_relief(slot_x, true);
            snap_relief(slot_x, false);
        }

        // Chamfer top edges
        translate([-1, -1, case_height])
            rotate([-45, 0, 0])
                cube([case_width + 2, 3, 3]);
        translate([-1, case_depth + 1, case_height])
            rotate([-45, 0, 0])
                translate([0, -3, 0])
                    cube([case_width + 2, 3, 3]);
    }
}

// Add slot numbers on front face
module labels() {
    label_depth = 0.8;
    label_size = 6;

    for (i = [0:num_batteries - 1]) {
        slot_center_x = wall + i * (slot_width + divider_thick) + slot_width/2;
        translate([slot_center_x, -0.1, case_height - 12])
            rotate([90, 0, 0])
                linear_extrude(height = label_depth)
                    text(str(i + 1), size = label_size, halign = "center", valign = "center", font = "Liberation Sans:style=Bold");
    }
}

// Grip ridges on sides
module grip_ridges() {
    ridge_height = 0.8;
    ridge_spacing = 5;
    ridge_width = case_depth - 20;

    for (z = [15 : ridge_spacing : case_height - 15]) {
        // Left side
        translate([-ridge_height, 10, z])
            rotate([0, 45, 0])
                cube([ridge_height * 1.5, ridge_width, ridge_height * 1.5]);
        // Right side
        translate([case_width, 10, z])
            rotate([0, 45, 0])
                cube([ridge_height * 1.5, ridge_width, ridge_height * 1.5]);
    }
}

// Complete battery case
module battery_case() {
    difference() {
        union() {
            case_body();

            // Add snap ridges to each slot
            for (i = [0:num_batteries - 1]) {
                slot_x = wall + i * (slot_width + divider_thick);
                slot_snaps(slot_x);
            }
        }

        // Add labels
        labels();

        // Grip ridges (cut into sides)
        grip_ridges();
    }
}

// Render the case
battery_case();
'}

